const { chromium } = require("playwright");
const http = require("http");
const fs = require("fs");
const path = require("path");

const WEB = path.resolve(__dirname, "web");
const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".png": "image/png",
  ".svg": "image/svg+xml",
  ".json": "application/json",
};

const server = http.createServer((req, res) => {
  const urlPath = decodeURIComponent((req.url || "/").split("?")[0]);
  let filePath = path.join(WEB, urlPath === "/" ? "index.html" : urlPath);
  if (!filePath.startsWith(WEB)) {
    res.writeHead(403);
    res.end();
    return;
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": MIME[path.extname(filePath)] || "application/octet-stream" });
    res.end(data);
  });
});

function listen() {
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(server.address().port)));
}

async function main() {
  const port = await listen();
  const origin = `http://127.0.0.1:${port}`;
  const browser = await chromium.launch({ channel: "chrome" });
  const findings = [];

  const fixture = await browser.newPage();
  await fixture.setViewportSize({ width: 430, height: 1400 });
  await fixture.goto(`${origin}/usability/mobile-dock-segment.html`, { waitUntil: "domcontentloaded" });
  await fixture.screenshot({
    path: path.join(WEB, "usability/mobile-dock-segment.png"),
    fullPage: true,
  });
  await fixture.close();

  const mobile = await browser.newPage();
  await mobile.setViewportSize({ width: 390, height: 844 });
  await mobile.goto(origin + "/", { waitUntil: "domcontentloaded" });
  await mobile.evaluate(() => {
    document.body.classList.add("trace-loaded-mobile", "playback-ready");
    const dock = document.getElementById("mobileTransport");
    dock.classList.add("visible");
    dock.setAttribute("aria-hidden", "false");
    const sidebar = document.getElementById("sidebar");
    sidebar.style.display = "flex";
  });
  await mobile.waitForTimeout(200);

  const mobileMetrics = await mobile.evaluate(() => {
    const dock = document.getElementById("mobileTransport");
    const dockRect = dock.getBoundingClientRect();
    const labels = [...dock.querySelectorAll("button")].map((btn) => ({
      label: (btn.getAttribute("aria-label") || "") + " " + (btn.querySelector("span")?.textContent || ""),
      width: Math.round(btn.getBoundingClientRect().width),
      height: Math.round(btn.getBoundingClientRect().height),
      top: Math.round(btn.getBoundingClientRect().top),
      overflow: btn.scrollWidth > btn.clientWidth + 1,
    }));
    const instructions = document.querySelector(".mobile-shortcuts");
    const desktopShortcuts = document.querySelector(".desktop-shortcuts");
    const sidebar = document.getElementById("sidebar");
    const sidebarStyle = getComputedStyle(sidebar);
    const padBottom = parseFloat(sidebarStyle.paddingBottom);
    const lastSection = sidebar.querySelector(".section:last-of-type");
    return {
      innerWidth: window.innerWidth,
      scrollWidth: document.documentElement.scrollWidth,
      dockDisplay: getComputedStyle(dock).display,
      dockHeight: Math.round(dockRect.height),
      dockBottom: Math.round(window.innerHeight - dockRect.bottom),
      dockTop: Math.round(dockRect.top),
      buttonCount: dock.querySelectorAll("button").length,
      labels,
      mobileInstructionsDisplay: getComputedStyle(instructions).display,
      desktopInstructionsDisplay: getComputedStyle(desktopShortcuts).display,
      mobileInstructionsText: instructions.innerText,
      sidebarPadBottom: padBottom,
      sidebarLastBottom: lastSection ? Math.round(lastSection.getBoundingClientRect().bottom) : null,
    };
  });
  findings.push({ viewport: "390 live dock", ...mobileMetrics });

  await mobile.screenshot({
    path: path.join(WEB, "usability/mobile-dock-segment-live.png"),
  });

  await mobile.evaluate(() => {
    document.querySelector("#sidebar .section:last-of-type").scrollIntoView({ block: "end" });
  });
  await mobile.waitForTimeout(150);
  await mobile.screenshot({
    path: path.join(WEB, "usability/mobile-dock-segment-instructions-live.png"),
  });

  const closed = await mobile.evaluate(() => {
    document.body.classList.add("mobile-panel-closed");
    const openBtn = document.getElementById("mobilePanelOpen");
    const dock = document.getElementById("mobileTransport");
    const openRect = openBtn.getBoundingClientRect();
    const dockRect = dock.getBoundingClientRect();
    return {
      openDisplay: getComputedStyle(openBtn).display,
      openBottom: Math.round(openRect.bottom),
      dockTop: Math.round(dockRect.top),
      overlap: openRect.bottom > dockRect.top + 1,
      canvasPad: getComputedStyle(document.getElementById("canvasWrap")).paddingBottom,
    };
  });
  findings.push({ viewport: "390 panel-closed", ...closed });

  const desktop = await browser.newPage();
  await desktop.setViewportSize({ width: 1280, height: 800 });
  await desktop.goto(origin + "/", { waitUntil: "domcontentloaded" });
  const desktopMetrics = await desktop.evaluate(() => {
    document.getElementById("playbackBar").classList.add("visible");
    const dock = document.getElementById("mobileTransport");
    const prefixBack = document.getElementById("prefixBackBtn");
    return {
      innerWidth: window.innerWidth,
      dockDisplay: getComputedStyle(dock).display,
      playbackBarDisplay: getComputedStyle(document.getElementById("playbackBar")).display,
      prefixBackVisible: prefixBack.getBoundingClientRect().width > 0,
      mobileInstructionsDisplay: getComputedStyle(document.querySelector(".mobile-shortcuts")).display,
      desktopInstructionsDisplay: getComputedStyle(document.querySelector(".desktop-shortcuts")).display,
    };
  });
  findings.push({ viewport: "1280 desktop", ...desktopMetrics });

  await browser.close();
  server.close();
  console.log(JSON.stringify(findings, null, 2));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

